import "../css/dashboard.css";

import logo from "../image/tybwhitelogo.png";

import { useNavigate } from "react-router-dom";

import { DatePicker } from "antd";

import HomeIcon from "@mui/icons-material/Home";

import { useEffect, useState } from "react";


const API_BASE_URL = "http://localhost:5000";


function Dashboard() {

    const navigate = useNavigate();


    // ============================================================
    // STATE
    // ============================================================

    const [resort, setResort] = useState("");

    const [month, setMonth] = useState("");

    const [year, setYear] = useState("");

    const [resorts, setResorts] = useState([]);

    const [productsSold, setProductsSold] = useState([]);

    const [loading, setLoading] = useState(false);


    // ============================================================
    // FETCH RESORT CUSTOMERS
    // ============================================================

    useEffect(() => {

        fetchResortCustomers();

    }, []);


    const fetchResortCustomers = async () => {

        try {

            const response = await fetch(
                `${API_BASE_URL}/api/resort-customers`
            );

            if (!response.ok) {

                throw new Error(
                    "Failed to fetch resort customers"
                );
            }

            const data = await response.json();

            setResorts(data);

        } catch (error) {

            console.error(
                "Error fetching resort customers:",
                error
            );

        }
    };


    // ============================================================
    // FETCH MONTHLY ORDERS
    // ============================================================

    const fetchMonthlyOrders = async (
        customerId,
        selectedMonth,
        selectedYear
    ) => {

        try {

            setLoading(true);

            const response = await fetch(
                `${API_BASE_URL}/api/resort-customers/${customerId}/monthly-orders?month=${selectedMonth}&year=${selectedYear}`
            );

            if (!response.ok) {

                throw new Error(
                    "Failed to fetch monthly orders"
                );
            }

            const data = await response.json();

            setProductsSold(data);

        } catch (error) {

            console.error(
                "Error fetching monthly orders:",
                error
            );

            setProductsSold([]);

        } finally {

            setLoading(false);
        }
    };


    // ============================================================
    // RESORT CHANGE
    // ============================================================

    const handleResortChange = (e) => {

        const customerId = e.target.value;

        setResort(customerId);

        // Clear previous results
        setProductsSold([]);

        // Fetch only when both resort and month are selected
        if (
            customerId &&
            month &&
            year
        ) {

            fetchMonthlyOrders(
                customerId,
                month,
                year
            );
        }
    };


    // ============================================================
    // MONTH / YEAR CHANGE
    // ============================================================

    const handleMMYYChange = (date) => {

        if (date) {

            const selectedMonth =
                date.month() + 1;

            const selectedYear =
                date.year();

            setMonth(selectedMonth);

            setYear(selectedYear);

            setProductsSold([]);


            // Fetch if resort is already selected
            if (resort) {

                fetchMonthlyOrders(
                    resort,
                    selectedMonth,
                    selectedYear
                );
            }

        } else {

            setMonth("");

            setYear("");

            setProductsSold([]);
        }
    };

    // ============================================================
// DETAIL MONTH / YEAR CHANGE
// ============================================================

const handleDetailMMYYChange = (date) => {

    if (date) {

        const selectedMonth = date.month() + 1;
        const selectedYear = date.year();

        setDetailMonth(selectedMonth);
        setDetailYear(selectedYear);
        setDetailOrders([]);

        if (detailCustomer) {
            fetchDetailOrders(
                detailCustomer,
                selectedMonth,
                selectedYear
            );
        }

    } else {

        setDetailMonth("");
        setDetailYear("");
        setDetailOrders([]);
    }
};


// ============================================================
// FETCH DETAILED RESORT ORDERS
// ============================================================

const fetchDetailOrders = async (
    customerId,
    selectedMonth,
    selectedYear
) => {

    try {

        setDetailLoading(true);

        const response = await fetch(
            `${API_BASE_URL}/api/resort-customers/${customerId}/monthly-order-details?month=${selectedMonth}&year=${selectedYear}`
        );

        if (!response.ok) {
            throw new Error(
                "Failed to fetch detailed orders"
            );
        }

        const data = await response.json();

        setDetailOrders(data);

    } catch (error) {

        console.error(
            "Error fetching detailed orders:",
            error
        );

        setDetailOrders([]);

    } finally {

        setDetailLoading(false);
    }
};


// ============================================================
// DETAIL CUSTOMER CHANGE
// ============================================================

const handleDetailCustomerChange = (e) => {

    const selectedCustomer = e.target.value;

    setDetailCustomer(selectedCustomer);
    setDetailOrders([]);

    if (
        !selectedCustomer ||
        !detailMonth ||
        !detailYear
    ) {
        return;
    }

    fetchDetailOrders(
        selectedCustomer,
        detailMonth,
        detailYear
    );
};


    // ============================================================
    // SELECTED RESORT
    // ============================================================

    const selectedResort = resorts.find(
        (r) =>
            String(r.resort_customer_id) ===
            String(resort)
    );


    // ============================================================
    // UI
    // ============================================================

    return (

        <div className="dashboardMain">


            {/* ====================================================
                HEADER
            ==================================================== */}

            <div className="header">

                <div className="headimg">

                    <img
                        src={logo}
                        alt="logo"
                    />

                    <br />

                    <span
                        style={{
                            color: "white",
                            paddingLeft: "20px"
                        }}
                    >
                        The Yercaud Bean
                    </span>

                </div>


                <div>

                    <button
                        onClick={() =>
                            navigate("/")
                        }
                    >
                        <HomeIcon />
                    </button>

                </div>

            </div>


            {/* ====================================================
                TITLE
            ==================================================== */}

            <h2>
                Dashboard
            </h2>


            {/* ====================================================
                FILTERS
            ==================================================== */}

            <div className="dashboardFilter">


                {/* RESORT */}

                <select
                    value={resort}
                    onChange={handleResortChange}
                >

                    <option
                        value=""
                        disabled
                        hidden
                    >
                        Select Resort
                    </option>


                    {resorts.map((r) => (

                        <option
                            key={
                                r.resort_customer_id
                            }
                            value={
                                r.resort_customer_id
                            }
                        >
                            {r.customer_name}
                        </option>

                    ))}

                </select>


                {/* MONTH */}

                <DatePicker
                    picker="month"
                    onChange={
                        handleMMYYChange
                    }
                />

            </div>


            {/* ====================================================
                RESULTS
            ==================================================== */}

            {
                resort &&
                month &&
                year && (

                    <div className="dasboardDisplay">


                        {/* RESORT NAME */}

                        <h2>
                            {
                                selectedResort?.customer_name
                            }
                        </h2>


                        {/* SELECTED MONTH */}

                        <p>
                            {String(month).padStart(2, "0")}
                            /
                            {year}
                        </p>


                        {/* LOADING */}

                        {loading && (

                            <p>
                                Loading...
                            </p>

                        )}


                        {/* PRODUCTS */}

                        {!loading &&
                            productsSold.length > 0 && (

                                <div className="productSalesDisplay">


                                    {productsSold.map(
                                        (
                                            prod,
                                            index
                                        ) => (

                                            <div
                                                className="productItem"
                                                key={
                                                    `${prod.item_name}-${prod.pack_size_grams}-${index}`
                                                }
                                            >

                                                <p>

                                                    {
                                                        prod.item_name
                                                    }

                                                    {
                                                        prod.pack_size_grams
                                                            ? ` (${prod.pack_size_grams}g)`
                                                            : ""
                                                    }

                                                </p>


                                                <p>

                                                    {
                                                        Number(
                                                            prod.total_quantity
                                                        )
                                                    }

                                                </p>

                                            </div>

                                        )
                                    )}

                                </div>

                            )}


                        {/* NO ORDERS */}

                        {!loading &&
                            productsSold.length === 0 && (

                                <p
                                    style={{
                                        color: "grey"
                                    }}
                                >
                                    No orders found for
                                    this resort in the
                                    selected month.
                                </p>

                            )}

                    </div>

                )

            }


<h2>Excel</h2>

<div className="detailedDisplayFilter">

    {/* CUSTOMER */}

    <select
        value={detailCustomer}
        onChange={handleDetailCustomerChange}
    >

        <option
            value=""
            disabled
            hidden
        >
            Select Customer
        </option>

        {resorts.map((r) => (

            <option
                key={r.resort_customer_id}
                value={r.resort_customer_id}
            >
                {r.customer_name}
            </option>

        ))}

    </select>


    {/* MONTH */}

    <DatePicker
        picker="month"
        onChange={handleDetailMMYYChange}
    />

</div>


{/* ============================================================
    DETAILED RESULTS
============================================================ */}

{
    detailCustomer &&
    detailMonth &&
    detailYear && (

        <div className="dasboardDisplay">

            <h2>
                {
                    resorts.find(
                        (r) =>
                            String(
                                r.resort_customer_id
                            ) ===
                            String(detailCustomer)
                    )?.customer_name
                }
            </h2>


            <p>
                {String(detailMonth).padStart(2, "0")}
                /
                {detailYear}
            </p>


            {/* LOADING */}

            {detailLoading && (

                <p>
                    Loading...
                </p>

            )}


            {/* TABLE */}

            {!detailLoading &&
                detailOrders.length > 0 && (

                    <div className="productSalesDetailDisplay">

                        <div className="productDetailDisplayItem">

                            <table>

                                <tbody>

                                    <tr>

                                        <th>
                                            Date
                                        </th>

                                        <th>
                                            Particulars
                                        </th>

                                        <th>
                                            Quantity
                                        </th>

                                        <th>
                                            Unit Price
                                        </th>

                                        <th>
                                            Total Price
                                        </th>

                                    </tr>


                                    {
                                        detailOrders.map(
                                            (order) => (

                                                order.products.map(
                                                    (
                                                        item,
                                                        productIndex
                                                    ) => (

                                                        <tr
                                                            key={
                                                                `${order.order_id}-${productIndex}`
                                                            }
                                                        >

                                                            <td>

                                                                {
                                                                    productIndex === 0
                                                                        ? order.date
                                                                        : ""
                                                                }

                                                            </td>


                                                            <td>

                                                                {
                                                                    item.name
                                                                }

                                                                {
                                                                    item.pack_size_grams
                                                                        ? ` (${item.pack_size_grams}g)`
                                                                        : ""
                                                                }

                                                            </td>


                                                            <td>

                                                                {
                                                                    item.quantity
                                                                }

                                                            </td>


                                                            <td>

                                                                ₹
                                                                {
                                                                    item.unit_price
                                                                }

                                                            </td>


                                                            <td>

                                                                {
                                                                    productIndex === 0
                                                                        ? `₹${order.total_price}`
                                                                        : ""
                                                                }

                                                            </td>

                                                        </tr>

                                                    )
                                                )

                                            )
                                        )
                                    }

                                </tbody>

                            </table>

                        </div>

                    </div>

                )
            }


            {/* NO ORDERS */}

            {!detailLoading &&
                detailOrders.length === 0 && (

                    <p
                        style={{
                            color: "grey"
                        }}
                    >
                        No orders found for the selected
                        customer and month.
                    </p>

                )
            }

        </div>

    )
}

        </div>
    );
}


export default Dashboard;
